The full route shuffle saturates the distance even at strength=1, so the fix limits the shuffle to a subset of routes whose size grows with `strength` (k+1 routes).

```python
class RouteCrossExchangeShuffle:
    def perturb(self, sol, strength: float, rng: Random):
        orig = list(sol)
        n = len(orig)
        if n < 2:
            return canonical(tuple(orig))
        routes = self._greedy_routes(orig)
        k = max(1, int(round(strength)))
        for _ in range(k):
            if len(routes) >= 2:
                i, j = rng.sample(range(len(routes)), 2)
                r1, r2 = routes[i], routes[j]
                l1 = rng.randint(1, min(self.max_seg_len, len(r1)))
                l2 = rng.randint(1, min(self.max_seg_len, len(r2)))
                p1 = rng.randint(0, len(r1) - l1)
                p2 = rng.randint(0, len(r2) - l2)
                s1, s2 = r1[p1:p1 + l1], r2[p2:p2 + l2]
                if rng.random() < 0.5:
                    s1 = s1[::-1]
                if rng.random() < 0.5:
                    s2 = s2[::-1]
                routes[i] = r1[:p1] + s2 + r1[p1 + l1:]
                routes[j] = r2[:p2] + s1 + r2[p2 + l2:]
                routes = [r for r in routes if r]
            else:
                r = routes[0]
                if len(r) >= 2:
                    a, b = sorted(rng.sample(range(len(r) + 1), 2))
                    if b - a < 2:
                        a, b = 0, len(r)
                    routes[0] = r[:a] + r[a:b][::-1] + r[b:]
        if self.shuffle_routes and len(routes) >= 2:
            m = min(len(routes), k + 1)
            pos = sorted(rng.sample(range(len(routes)), m))
            chosen = [routes[p] for p in pos]
            perm = list(range(m))
            rng.shuffle(perm)
            if perm == list(range(m)):
                perm = perm[1:] + perm[:1]
            new_routes = list(routes)
            for idx, p in enumerate(pos):
                new_routes[p] = chosen[perm[idx]]
            routes = new_routes
        t = [c for r in routes for c in r]
        if t == orig:
            i, j = rng.sample(range(n), 2)
            t = list(orig)
            t[i], t[j] = t[j], t[i]
        return canonical(tuple(t))
